551	    @Transactional
552	    public void updateShipmentStatuses() {
553	        log.info("전체 배송 상태 업데이트 시작");
554	
555	
556	        List<Xhx14> shipments = orderShipmentRepository.findByStatusIn(
557	                List.of(Xpb98Status.IN_TRANSIT, Xpb98Status.OUT_FOR_DELIVERY)
558	        );
559	
560	        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());
561	
562	        int successCount = 0;
563	        int errorCount = 0;
564	
565	        for (Xhx14 shipment : shipments) {
566	            try {
567	                String trackingNumber = shipment.getTrackingNumber();
568	                if (trackingNumber == null || trackingNumber.isBlank()) {
569	                    log.warn("운송장 번호가 없는 배송건 스킵: shipmentId={}", shipment.getId());
570	                    errorCount++;
571	                    continue;
572	                }
573	
574	                log.debug("배송 상태 조회 시작: shipmentId={}, trackingNumber={}",
575	                        shipment.getId(), trackingNumber);
576	
577	
578	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
579	                Xpb98Status newStatus = mapToShipmentStatus(currentStatus);
580	
581	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}, newStatus={}",
582	                        shipment.getId(), currentStatus, newStatus);
583	
584	
585	                if (shipment.getStatus() == newStatus) {
586	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
587	                            shipment.getId(), newStatus);
588	                    successCount++;
589	                    continue;
590	                }
591	
592	
593	                if (newStatus == Xpb98Status.DELIVERED) {
594	                    log.info("배송 완료 처리: shipmentId={}", shipment.getId());
595	
596	                    shipment.updateStatus(newStatus);
597	                    Xdg64 order = shipment.getOrder();
598	                    order.updateStatus(Xdg64Status.COMPLETED);
599	
600	
601	                    Xrd81 buyer = order.getUser();
602	                    notificationCommandService.createNotification(
603	                            buyer.getId(),
604	                            Xzv64.SHOPPING,
605	                            Xkh73Type.BID,
606	                            "상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
607	                    );
608	
609	                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
610	                            buyer.getId(), order.getId());
611	
