   546	    @Override
   547	    public Xhx14 process(Xhx14 orderShipment) throws Exception {
   548	        String trackingNumber = orderShipment.getTrackingNumber();
   549	        Long shipmentId = orderShipment.getId();
   550	
   551	        if (trackingNumber == null || trackingNumber.isBlank()) {
   552	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
   553	            throw new Xpb98Exception(Xpb98ErrorCode.TRACKING_NUMBER_INVALID);
   554	        }
   555	
   556	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
   557	                shipmentId, trackingNumber, orderShipment.getStatus());
   558	
   559	        Page page = null;
   560	        try {
   561	
   562	            page = browserManager.newPage();
   563	            if (page == null) {
   564	                throw new Xpb98Exception(Xpb98ErrorCode.BROWSER_INITIALIZATION_ERROR);
   565	            }
   566	
   567	
   568	            page.setDefaultTimeout(TIMEOUT_MS);
   569	
   570	
   571	            String url = TRACKING_URL_PREFIX + trackingNumber;
   572	            log.debug("배송 조회 페이지로 이동: {}", url);
   573	            page.navigate(url);
   574	
   575	
   576	            log.debug("배송 상태 테이블 로드 대기");
   577	            page.waitForSelector(STATUS_SELECTOR);
   578	
   579	
   580	            String renderedHtml = page.content();
   581	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
   582	
   583	
   584	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
   585	            Xpb98Status newStatus = mapToShipmentStatus(statusText);
   586	
   587	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
   588	                    shipmentId, statusText, newStatus);
   589	
   590	
   591	            if (orderShipment.getStatus() == newStatus) {
   592	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
   593	                        shipmentId, newStatus);
   594	                return orderShipment;
   595	            }
   596	
   597	
   598	            if (newStatus == Xpb98Status.DELIVERED) {
   599	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
   600	                        shipmentId, orderShipment.getOrder().getId());
   601	
   602	
   603	                orderShipment.updateStatus(Xpb98Status.DELIVERED);
   604	
   605	
   606	                orderService.completeOrder(orderShipment.getOrder().getId());
   607	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
   608	
   609	            } else if (newStatus == Xpb98Status.OUT_FOR_DELIVERY) {
   610	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
   611	                orderShipment.updateStatus(Xpb98Status.OUT_FOR_DELIVERY);
   612	
   613	            } else {
   614	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
   615	                orderShipment.updateStatus(Xpb98Status.IN_TRANSIT);
   616	            }
   617	
   618	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
   619	                    shipmentId, orderShipment.getStatus());
   620	
   621	            return orderShipment;
   622	
   623	        } catch (Exception e) {
   624	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
   625	                    shipmentId, trackingNumber, e.getMessage(), e);
   626	
   627	
   628	            if (!(e instanceof Xpb98Exception)) {
   629	                throw new Xpb98Exception(
   630	                        Xpb98ErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
   631	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
   632	                        e
   633	                );
   634	            }
   635	            throw e;
   636	        } finally {
   637	
   638	            if (page != null) {
   639	                try {
   640	                    page.close();
   641	                    log.debug("페이지 리소스 해제 완료");
   642	                } catch (Exception e) {
   643	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
   644	                }
   645	            }
   646	        }
   647	    }
