   664	                throw new Xpb98Exception(
   665	                        Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
   666	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
   667	                );
   668	            }
   669	
   670	
   671	            String statusText = rows.last().select("td").get(4).text().trim();
   672	
   673	            if (statusText.isEmpty()) {
   674	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
   675	                throw new Xpb98Exception(
   676	                        Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
   677	                        "배송 상태 정보를 찾을 수 없습니다."
   678	                );
   679	            }
   680	
   681	            return statusText;
   682	
   683	        } catch (IndexOutOfBoundsException e) {
   684	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
   685	            throw new Xpb98Exception(
   686	                    Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
   687	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
   688	                    e
   689	            );
   690	        } catch (Exception e) {
   691	            if (e instanceof Xpb98Exception) {
   692	                throw (Xpb98Exception) e;
   693	            }
   694	
   695	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
   696	            throw new Xpb98Exception(
   697	                    Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
   698	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
   699	                    e
